<div class="section-heading"><div><h2><?= e(t('Project analytics')) ?></h2><p class="muted"><?= e(t('Real work-item state, recorded effort and progress history.')) ?></p></div><span class="badge"><?= e(t('No sample data')) ?></span></div><div class="work-stats"><?php foreach([['Work items',$analytics['stats']['total']],['Completed',$analytics['stats']['completed']],['Overdue',$analytics['stats']['overdue']],['Tracked time',number_format($analytics['minutes']/60,1).' h']] as [$label,$count]): ?><section class="card"><span><?= e($label) ?></span><strong><?= e($count) ?></strong></section><?php endforeach; ?></div>
<div class="two-col"><section class="card"><h2><?= e(t('Workflow distribution')) ?></h2><?php if($analytics['stats']['total']): ?><?= chart('doughnut',array_column($analytics['byState'],'name'),[['label'=>t('Work items'),'data'=>array_column($analytics['byState'],'total'),'backgroundColor'=>array_column($analytics['byState'],'color')]],['cutout'=>'68%']) ?><?php else: ?><div class="empty"><h3><?= e(t('No work items yet.')) ?></h3><p><?= e(t('Your workflow chart appears after creating work items.')) ?></p></div><?php endif; ?></section><section class="card"><h2><?= e(t('Priority breakdown')) ?></h2><?php if($analytics['byPriority']): ?><?= chart('bar',array_map(fn($row)=>WorkService::PRIORITIES[$row['priority']],$analytics['byPriority']),[['label'=>t('Work items'),'data'=>array_column($analytics['byPriority'],'total'),'backgroundColor'=>'#3688ff']],['scales'=>['y'=>['beginAtZero'=>true,'ticks'=>['precision'=>0]]]]) ?><?php else: ?><div class="empty"><p><?= e(t('No priority data yet.')) ?></p></div><?php endif; ?></section></div>
<section class="card"><h2><?= e(t('Progress over time')) ?></h2><?php if($analytics['history']): ?><?= chart('line',array_column($analytics['history'],'day'),[['label'=>t('Total work items'),'data'=>array_column($analytics['history'],'total'),'borderColor'=>'#94a3b8'],['label'=>t('Completed'),'data'=>array_column($analytics['history'],'completed'),'borderColor'=>'#22b37e']],['scales'=>['y'=>['beginAtZero'=>true,'ticks'=>['precision'=>0]]]]) ?><p class="footnote"><?= e(t('Daily snapshots are recorded from real changes. Dates before your first update are not filled with estimates.')) ?></p><?php else: ?><p class="muted"><?= e(t('Progress snapshots appear as work items change.')) ?></p><?php endif; ?></section>
<section class="card"><h2><?= e(t('Assignee workload')) ?></h2><?php if(!$analytics['byPerson']): ?><p class="muted"><?= e(t('Assign work items to people to see their workload.')) ?></p><?php else:foreach($analytics['byPerson'] as $person): ?><article class="work-workload"><span class="work-avatar"><?= e(mb_substr($person['name'],0,1)) ?></span><strong><?= e($person['name']) ?></strong><span><?= e($person['total']) ?> <?= e(t('assigned ·')) ?> <?= e($person['completed']) ?> <?= e(t('completed')) ?></span></article><?php endforeach; ?><p class="footnote"><?= e(t('A work item assigned to more than one person is counted for each assignee.')) ?></p><?php endif; ?></section>
